CREATE TABLE "store" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "store_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"slug" text NOT NULL,
	"name" text NOT NULL,
	"whatsappNumber" text,
	"instagramUrl" text,
	"tiktokUrl" text,
	"currencyCode" "currency_code" NOT NULL,
	"logoUrl" text,
	"isActive" boolean NOT NULL,
	"colorBackground" text NOT NULL,
	"colorSurface" text NOT NULL,
	"colorForeground" text NOT NULL,
	"colorContrast" text NOT NULL,
	"colorAccent" text NOT NULL,
	"createdAt" timestamp (3) with time zone DEFAULT now() NOT NULL,
	"updatedAt" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "store_slug_unique" UNIQUE("slug"),
	CONSTRAINT "store_slug_format" CHECK ("store"."slug" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' AND char_length("store"."slug") BETWEEN 2 AND 40),
	CONSTRAINT "store_slug_not_reserved" CHECK ("store"."slug" NOT IN ('admin', 'api', 'design', 'en', 'es', 'monitoring')),
	CONSTRAINT "store_color_background_hex" CHECK ("store"."colorBackground" ~ '^#[0-9a-f]{6}$'),
	CONSTRAINT "store_color_surface_hex" CHECK ("store"."colorSurface" ~ '^#[0-9a-f]{6}$'),
	CONSTRAINT "store_color_foreground_hex" CHECK ("store"."colorForeground" ~ '^#[0-9a-f]{6}$'),
	CONSTRAINT "store_color_contrast_hex" CHECK ("store"."colorContrast" ~ '^#[0-9a-f]{6}$'),
	CONSTRAINT "store_color_accent_hex" CHECK ("store"."colorAccent" ~ '^#[0-9a-f]{6}$')
);
